import React from 'react';
import styled from 'styled-components';

const ProjectsSection = styled.section`
  width: 100%;
  padding: 4rem 0 2rem 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: ${({ theme }) => theme.bg};
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 2.5rem;
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
`;

const ProjectCard = styled.div`
  background: #111;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 16px 0 rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  transition: transform 0.18s cubic-bezier(0.4,0,0.2,1), box-shadow 0.18s cubic-bezier(0.4,0,0.2,1);
  &:hover {
    transform: translateY(-6px) scale(1.025);
    box-shadow: 0 6px 32px 0 rgba(0,0,0,0.18);
  }
`;

const ProjectImage = styled.div`
  width: 100%;
  aspect-ratio: 4/3;
  background: #222;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  color: #aaa;
  font-weight: 500;
`;

const ProjectInfo = styled.div`
  padding: 1.2rem 1.5rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
`;

const ProjectTitle = styled.h3`
  color: #fff;
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
`;

const ProjectDesc = styled.p`
  color: #aaa;
  font-size: 1rem;
  margin-bottom: 0.5rem;
`;

// Placeholder images and info
const projects = [
  {
    title: 'SaaS Dashboard',
    desc: 'Modern dashboard UI for SaaS analytics.',
    img: 'https://via.placeholder.com/600x400?text=Project+1',
  },
  {
    title: 'Creative Agency',
    desc: 'Portfolio site for a creative agency.',
    img: 'https://via.placeholder.com/600x400?text=Project+2',
  },
  {
    title: 'Medical App',
    desc: 'UI for a healthcare mobile app.',
    img: 'https://via.placeholder.com/600x400?text=Project+3',
  },
  {
    title: 'Finance Tool',
    desc: 'Clean UI for a finance dashboard.',
    img: 'https://via.placeholder.com/600x400?text=Project+4',
  },
  {
    title: 'Travel Platform',
    desc: 'Landing page for a travel booking platform.',
    img: 'https://via.placeholder.com/600x400?text=Project+5',
  },
  {
    title: 'Outdoor Blog',
    desc: 'Blog UI for outdoor adventures.',
    img: 'https://via.placeholder.com/600x400?text=Project+6',
  },
];

const Projects = () => (
  <ProjectsSection id="projects">
    <ProjectsGrid>
      {projects.map((project, idx) => (
        <ProjectCard key={idx}>
          <ProjectImage as="img" src={project.img} alt={project.title} />
          <ProjectInfo>
            <ProjectTitle>{project.title}</ProjectTitle>
            <ProjectDesc>{project.desc}</ProjectDesc>
          </ProjectInfo>
        </ProjectCard>
      ))}
    </ProjectsGrid>
  </ProjectsSection>
);

export default Projects;
